    color: String,

    /// Force dumping operations into a file even in dry-run mode
    #[arg(long)]
    dump: bool,

    /// Set the dump file prefix
    #[arg(long, default_value = "rnr-")]
    dump_prefix: String,

    /// Do not dump operations into a file
    #[arg(long)]
    no_dump: bool,

    /// Limit of replacements, all matches if set to 0
    #[arg(short = 'l', long, value_name = "LIMIT")]
    replace_limit: Option<usize>,

    /// Apply a transformation to replacements including captured groups
    #[arg(short = 't', long, value_parser = ["upper", "lower", "ascii"])]
    replace_transform: Option<String>,

    /// Rename matching directories
    #[arg(short = 'D', long)]
    include_dirs: bool,

    /// Recursive mode
    #[arg(short = 'r', long)]
    recursive: bool,

    /// Set max depth in recursive mode
    #[arg(short = 'd', long, value_name = "LEVEL")]
    max_depth: Option<usize>,

    /// Include hidden files and directories
    #[arg(short = 'x', long)]
    hidden: bool,
}

#[derive(Parser)]
struct FromFileArgs {
    #[arg(value_name = "DUMPFILE")]
    dumpfile: String,

    /// Only show what would be done (default mode)
    #[arg(short = 'n', long)]
    dry_run: bool,

