    silent: bool,

    /// Set color output mode
    #[arg(long, default_value = "auto", value_parser = ["always", "never", "auto"])]
    color: String,

    /// Force dumping operations into a file even in dry-run mode
    #[arg(long)]
    dump: bool,

    /// Set the dump file prefix
    #[arg(long, default_value = "rnr-")]
    dump_prefix: String,

    /// Do not dump operations into a file
    #[arg(long)]
    no_dump: bool,

    /// Undo the operations from the dump file
    #[arg(short = 'u', long)]
    undo: bool,
}

#[derive(Parser)]
struct ToAsciiArgs {
    /// Target paths
    #[arg(value_name = "PATH(S)")]
    paths: Vec<String>,

    /// Only show what would be done (default mode)
    #[arg(short = 'n', long)]
    dry_run: bool,

