    /// Recursive mode
    #[arg(short = 'r', long)]
    recursive: bool,

    /// Set max depth in recursive mode
    #[arg(short = 'd', long, value_name = "LEVEL")]
    max_depth: Option<usize>,

    /// Include hidden files and directories
    #[arg(short = 'x', long)]
    hidden: bool,
}

fn main() {
    let cli = Cli::parse();
