{"command":"cat << 'EOF' > main.py
import sys
import os
import re
import json
import shutil
import unicodedata
from datetime import datetime
import argparse

from helps import *

def print_help_and_exit(text, code=0):
    print(text, end='')
    sys.exit(code)

def unidecode_like(text):
    return unicodedata.normalize('NFKD', text).encode('ascii', 'ignore').decode('utf-8')

class ClapArgumentParser(argparse.ArgumentParser):
    def error(self, message):
        print(f"error: {message}\n", file=sys.stderr)
        usage = self.format_usage()
        if usage.startswith("usage: "):
            usage = "Usage: " + usage[7:]
        print(usage, end='', file=sys.stderr)
        print("\nFor more information, try '--help'.", file=sys.stderr)
        sys.exit(2)

def convert_rust_replacement_to_python(repl):
    repl = repl.replace('\\', '\\\\')
    repl = repl.replace('$$', '\x00')
    repl = re.sub(r'\$\{([a-zA-Z0-9_]+)\}', r'\\g<\1>', repl)
    repl = re.sub(r'\$([0-9]+)', r'\\g<\1>', repl)
    repl = re.sub(r'\$([a-zA-Z_][a-zA-Z0-9_]*)', r'\\g<\1>', repl)
    repl = repl.replace('\x00', '\\$')
    return repl

def pcolor(text, code, color_mode):
    if color_mode == 'always' or (color_mode == 'auto' and sys.stdout.isatty()):
        return f"\033[{code}m{text}\033[0m"
    return text

def get_colored_diff(old, new, color_mode):
    if color_mode == 'never' or (color_mode == 'auto' and not sys.stdout.isatty()):
        return new

    p = 0
    while p < min(len(old), len(new)) and old[p] == new[p]:
        p += 1
    s = 0
    while s < min(len(old)-p, len(new)-p) and old[-s-1] == new[-s-1]:
        s += 1

    if s == 0:
        prefix = new[:p]
        changed = new[p:]
        suffix = ""
    else:
        prefix = new[:p]
        changed = new[p:-s]
        suffix = new[-s:]

    res = ""
    if prefix: res += pcolor(prefix, "32", color_mode)
    if changed: res += pcolor(changed, "1;31", color_mode)
    if suffix: res += pcolor(suffix, "32", color_mode)
    return res

def gather_paths(paths_arg, recursive, max_depth, hidden, include_dirs):
    res = {}
    def walk(p, current_depth):
        try:
            if not os.path.exists(p): return
            is_dir = os.path.isdir(p)
            if not is_dir or include_dirs:
                if p not in res or current_depth > res[p]:
                    res[p] = current_depth
            if is_dir and recursive:
                if max_depth is not None and current_depth >= max_depth:
                    return
                for entry in os.scandir(p):
                    if not hidden and entry.name.startswith('.'):
                        continue
                    walk(entry.path, current_depth + 1)
        except Exception:
            pass

    for p in paths_arg:
        p = p.rstrip('/')
        if not p: p = '/'
        walk(p, 0)
    return [(p, d) for p, d in res.items()]

def main():
    if len(sys.argv) < 2:
        print_help_and_exit(HELP_MAIN, 2)

    cmd = sys.argv[1]
    if cmd in ('-h', '--help', 'help'):
        print_help_and_exit(HELP_MAIN, 0)
    elif cmd in ('-V', '--version'):
        print_help_and_exit(HELP_VERSION, 0)

    if cmd == 'regex':
        if '-h' in sys.argv or '--help' in sys.argv:
            print_help_and_exit(HELP_REGEX, 0)
    elif cmd == 'from-file':
        if '-h' in sys.argv or '--help' in sys.argv:
            print_help_and_exit(HELP_FROM_FILE, 0)
    elif cmd == 'to-ascii':
        if '-h' in sys.argv or '--help' in sys.argv:
            print_help_and_exit(HELP_TO_ASCII, 0)

    parser = ClapArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='command')

    # regex
    rp = subparsers.add_parser('regex', add_help=False)
    rp.add_argument('expression')
    rp.add_argument('replacement')
    rp.add_argument('paths', nargs='+')
    rp.add_argument('-n', '--dry-run', action='store_true', default=True) # dry-run is default! Wait, if default is true, how to turn off? --force!
    rp.add_argument('-f', '--force', action='store_true')
    rp.add_argument('-b', '--backup', action='store_true')
    rp.add_argument('-s', '--silent', action='store_true')
    rp.add_argument('--color', default='auto')
    rp.add_argument('--dump', action='store_true')
    rp.add_argument('--dump-prefix', default='rnr-')
    rp.add_argument('--no-dump', action='store_true')
    rp.add_argument('-l', '--replace-limit', type=int, default=1)
    rp.add_argument('-t', '--replace-transform')
    rp.add_argument('-D', '--include-dirs', action='store_true')
    rp.add_argument('-r', '--recursive', action='store_true')
    rp.add_argument('-d', '--max-depth', type=int)
    rp.add_argument('-x', '--hidden', action='store_true')

    # to-ascii
    tp = subparsers.add_parser('to-ascii', add_help=False)
    tp.add_argument('paths', nargs='+')
    tp.add_argument('-n', '--dry-run', action='store_true', default=True)
    tp.add_argument('-f', '--force', action='store_true')
    tp.add_argument('-b', '--backup', action='store_true')
    tp.add_argument('-s', '--silent', action='store_true')
    tp.add_argument('--color', default='auto')
    tp.add_argument('--dump', action='store_true')
    tp.add_argument('--dump-prefix', default='rnr-')
    tp.add_argument('--no-dump', action='store_true')
    tp.add_argument('-D', '--include-dirs', action='store_true')
    tp.add_argument('-r', '--recursive', action='store_true')
    tp.add_argument('-d', '--max-depth', type=int)
    tp.add_argument('-x', '--hidden', action='store_true')

    # from-file
    fp = subparsers.add_parser('from-file', add_help=False)
    fp.add_argument('dumpfile')
    fp.add_argument('-n', '--dry-run', action='store_true', default=True)
    fp.add_argument('-f', '--force', action='store_true')
    fp.add_argument('-b', '--backup', action='store_true')
    fp.add_argument('-s', '--silent', action='store_true')
    fp.add_argument('--color', default='auto')
    fp.add_argument('--dump', action='store_true')
    fp.add_argument('--dump-prefix', default='rnr-')
    fp.add_argument('--no-dump', action='store_true')
    fp.add_argument('-u', '--undo', action='store_true')

    # Catch argparse errors to match clap missing args
    try:
        args = parser.parse_args()
    except SystemExit as e:
        sys.exit(e.code)

    dry_run = not args.force
    color = args.color

    ops = []

    if args.command == 'from-file':
        try:
            with open(args.dumpfile, 'r') as f:
                data = json.load(f)
            # from-file just reads operations
            # in from-file, depth grouping might not be needed if they are already sorted, but let's compute depth
            for item in data.get('operations', []):
                src = item['source']
                tgt = item['target']
                if args.undo:
                    src, tgt = tgt, src
                depth = len(src.split('/'))
                ops.append({
                    'source': src,
                    'target': tgt,
                    'depth': depth
                })
        except Exception as e:
            print(f"Error reading dump file: {e}")
            sys.exit(1)
    else:
        # regex or to-ascii
        paths_list = gather_paths(args.paths, args.recursive, args.max_depth, args.hidden, args.include_dirs)
        if args.command == 'regex':
            try:
