                    target = os.path.join(dir_name, new_base)
                else:
                    target = new_base
                ops.append({
                    "source": path_obj,
                    "target": target,
                    "depth": depth,
                    "dir_name": dir_name,
                    "base_name": base_name,
                    "new_base": new_base
                })

    ops.sort(key=lambda x: (-x['depth'], x['source']))

    seen = {}
    has_conflict = False
    for op in ops:
        target = op['target']
        if target in seen:
            if not has_conflict:
                print("Error: Files will have the same name\n")
                has_conflict = True
            print(f"{seen[target]}->{target}")
            print(f"{op['source']}->{target}\n")
        else:
            seen[target] = op['source']

    if has_conflict:
        sys.exit(1)

    for op in ops:
        target = op['target']
        if args.command != 'from-file':
            if os.path.exists(target) and op['source'] != target:
                print(f"Error: Conflict with existing path {op['source']} -> {target}")
                sys.exit(1)

    if (args.dump) or (not dry_run and not args.no_dump):
        if ops:
            dump_data = {
                "date": datetime.now().strftime('%Y-%m-%d %H:%M:%S'),
                "operations": [{"source": o['source'], "target": o['target']} for o in ops]
            }
            dump_file = f"{args.dump_prefix}{datetime.now().strftime('%Y-%m-%d_%H%M%S')}.json"
            with open(dump_file, 'w') as f:
                json.dump(dump_data, f, indent=2)

    depth_groups = defaultdict(list)
    for op in ops:
        depth_groups[op['depth']].append(op)

    sorted_depths = sorted(depth_groups.keys(), reverse=True)

    if dry_run and not args.silent:
        print(pcolor("This is a DRY-RUN", "1", color))

    for d in sorted_depths:
        group = depth_groups[d]
        for op in group:
            source = op['source']
            target = op['target']

            if not args.silent:
                dir_name = op['dir_name']
                base_name = op['base_name']
                new_base = op['new_base']

                s_dir = f"{dir_name}/" if dir_name else ""
                t_dir = f"{dir_name}/" if dir_name else ""

                colored_diff = get_colored_diff(base_name, new_base, color)

                s_str = pcolor(s_dir, "38;5;8", color) + pcolor(base_name, "38;5;8", color)
                t_str = pcolor(t_dir, "32", color) + colored_diff

                if dry_run:
                    print(f"{s_str} -> {t_str}")
                else:
                    if args.backup and os.path.isfile(source):
                        bk_target = source + ".bk"
                        shutil.copy2(source, bk_target)
                        print(f"Info:  Backup created - {source} -> {bk_target}")

                    try:
                        os.rename(source, target)
                        print(f"{s_str} -> {t_str}")
                    except Exception as e:
                        print(f"Error: Cannot rename {source} -> {target}")
                        print(f"{e.strerror} (os error {e.errno})")
                        sys.exit(1)

if __name__ == '__main__':
    main()
